package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.WorkerAuthorizationService.*;
import java.time.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Actual original 201-member partial P1/P2 inputs; network callbacks are fictional. */
class WorkerPartialClaimScopeTest {
    SourcePartialDispatchReadinessTest f;GenerationJdbcStoreTest db;JdbcWorkerState state;JdbcJobRecords records;WorkerJdbcStore store;WorkerAuthorizationService worker;Clock clock;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup()throws Exception{f=new SourcePartialDispatchReadinessTest(){@Override GenerationJdbcStoreTest database(){return WorkerPartialClaimScopeTest.this.database();}};f.setup();db=f.db;WorkerCandidateSelectionScopeTest.installWorker(db);state=new JdbcWorkerState(db.source);records=new JdbcJobRecords(db.source);clock=f.q.clock;store=provider(f.service);worker=new WorkerAuthorizationService(db.writes,store,clock,n->0,()->true);}
    WorkerJdbcStore provider(DispatchReadinessService readiness){return new WorkerJdbcStore(state,records,"fictional-partial-claim-owner",()->false,readiness,clock,new DataSourceTransactionManager(db.source));}
    SharedWriteExecutor.ActionContext action(){return new SharedWriteExecutor.ActionContext("fictional-real-partial-claim","fictional-partial-claim-receipt",null);}
    @Test void ActualOriginalPartialCandidateClaimsAndSendsOnceWithoutDefaultPermission()throws Exception{setup();var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());var id=claim.permit().identity();assertTrue(f.roots.contains(id.rootId()));assertEquals(1,records.byId(id.rootId()).callCount());AtomicInteger sends=new AtomicInteger();assertEquals(State.SENT,worker.dispatch(claim.permit(),json->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(id.frozenRequestJson(),json);sends.incrementAndGet();return "fictional-result";}).state());assertEquals(1,sends.get());assertEquals(1,db.count("target_type='worker_claim'"));assertEquals(1,db.count("target_type='worker_send'"));String other=f.roots.stream().filter(root->!root.equals(id.rootId())).findFirst().orElseThrow();db.jdbc.update("DELETE FROM jobs WHERE owner_job_id=? AND record_kind='snapshot_part' AND purpose='input'",other);worker=new WorkerAuthorizationService(db.writes,provider(f.service),clock,n->0,()->true);var replay=worker.claim(action());assertEquals(id,replay.permit().identity());assertEquals(State.UNKNOWN,worker.dispatch(replay.permit(),json->{sends.incrementAndGet();return "must not send";}).state());assertEquals(1,sends.get());assertEquals(1,records.byId(id.rootId()).callCount());}
    @Test void ActualP1ChangeInsideWriterAndMemberChangeAfterCaptureCannotConsumeBudget()throws Exception{setup();String p1=f.q.q.a.f.plan.chunks().getLast().rootId();var changed=spy(f.q.q.a.service);doAnswer(c->{db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p1);return c.callRealMethod();}).when(changed).verify(any(),any());store=provider(f.provider(changed));worker=new WorkerAuthorizationService(db.writes,store,clock,n->0,()->true);assertThrows(RuntimeException.class,()->worker.claim(action()));assertEquals(0,db.count("target_type='worker_claim'"));assertEquals("free",state.slot().state());store=provider(f.service);var scope=store.captureClaim(action(),clock.instant());var chosen=db.writes.execute(new SharedWriteExecutor.ActionContext("fictional-observe-captured-candidate","fictional-observe",null),k->null,c->scope.candidates(clock.instant())).getFirst();String member=f.plan.chunks().stream().filter(part->part.rootId().equals(chosen.rootId())).findFirst().orElseThrow().itemIds().getFirst();db.jdbc.update("UPDATE source_run_items SET revision=revision+1 WHERE id=?",member);assertThrows(RuntimeException.class,()->db.writes.execute(action(),k->null,c->scope.reserve(chosen,"fictional-hint",clock.instant().plusSeconds(150),clock.instant(),c.actionKey())));assertEquals(0,records.byId(chosen.rootId()).callCount());assertEquals(0,db.count("target_type='worker_claim'"));assertEquals("free",state.slot().state());}
    @Test void ClaimReceiptFailureRollsBackSlotAttemptBudgetAndCanRecoverSameAction()throws Exception{setup();db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_partial_claim_receipt CHECK(target_type IS NULL OR target_type<>'worker_claim')");assertThrows(RuntimeException.class,()->worker.claim(action()));assertEquals("free",state.slot().state());assertEquals(0,state.slot().fencing());for(String root:f.roots){assertEquals(0,records.byId(root).callCount());assertEquals("queued",records.byId(root).state());}assertEquals(0,db.count("target_type='worker_claim'"));db.jdbc.execute("ALTER TABLE jobs DROP "+(db.source instanceof org.h2.jdbcx.JdbcDataSource?"CONSTRAINT ":"CHECK ")+"fictional_partial_claim_receipt");assertEquals(State.CLAIMED,worker.claim(action()).state());assertEquals(1,state.slot().fencing());assertEquals(1,db.count("target_type='worker_claim'"));}
}
